

-- ================= DDL =================
CREATE TABLE IF NOT EXISTS resource_textbook (
                                                 id BIGINT NOT NULL AUTO_INCREMENT,
                                                 subject VARCHAR(20) NOT NULL DEFAULT 'math',
                                                 version VARCHAR(20) NOT NULL DEFAULT 'suke' COMMENT '版本 key：suke/renjiao/bsd/zj/hk',
                                                 stage VARCHAR(10) NOT NULL DEFAULT 'junior' COMMENT '学段：primary/junior/senior',
                                                 name VARCHAR(100) NOT NULL COMMENT '教材名，如：七年级上册 苏科版',
                                                 grade VARCHAR(20) DEFAULT NULL COMMENT '年级，如：七年级上册 / 高一',
                                                 sort_order INT NOT NULL DEFAULT 0,
                                                 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                 PRIMARY KEY (id),
                                                 KEY idx_tb_subject (subject), KEY idx_tb_version (version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS resource_chapter (
                                                id BIGINT NOT NULL AUTO_INCREMENT,
                                                textbook_id BIGINT NOT NULL,
                                                name VARCHAR(100) NOT NULL COMMENT '章节名，如：第1章 有理数',
                                                chapter VARCHAR(50) DEFAULT NULL COMMENT '章节简称，如：有理数',
                                                sort_order INT NOT NULL DEFAULT 0,
                                                created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                PRIMARY KEY (id),
                                                KEY idx_ch_tb (textbook_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS resource_section (
                                                id BIGINT NOT NULL AUTO_INCREMENT,
                                                chapter_id BIGINT NOT NULL,
                                                name VARCHAR(100) NOT NULL COMMENT '小节名，如：1.1 正数与负数',
                                                sort_order INT NOT NULL DEFAULT 0,
                                                created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                PRIMARY KEY (id),
                                                KEY idx_sec_ch (chapter_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

